def compute(vars):
    total_sales = vars["v1"]
    international_sales_percentage = vars["v2"]
    value = total_sales * international_sales_percentage / 100

    return {
        "value": value,
        "trace": {
            "total_sales": total_sales,
            "international_sales_percentage": international_sales_percentage,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
